--
-- Disparadores `tramites`
--
DELIMITER $$
CREATE TRIGGER `trg_cuenta_catastral_auto` BEFORE INSERT ON `tramites` FOR EACH ROW SET NEW.cuenta_catastral = IF(NEW.cuenta_catastral IS NULL OR TRIM(NEW.cuenta_catastral) = '', CONCAT(YEAR(NOW()), LPAD((SELECT COALESCE(MAX(CAST(cuenta_catastral AS UNSIGNED)), 0) + 1 FROM sistema.tramites WHERE cuenta_catastral REGEXP '^[0-9]+$'), 6, '0')), NEW.cuenta_catastral)
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_historial_insert` AFTER INSERT ON `tramites` FOR EACH ROW INSERT INTO sistema.historial_tramites (tramite_id, usuario_id, accion, estatus_nuevo, comentario) VALUES (NEW.id, NEW.usuario_creador_id, 'Creado', NEW.estatus, 'Tramite creado en el sistema')
$$
DELIMITER ;

